//! SSH connections (Settings → SSH): servers the hub reaches with keys it holds, attached to
//! projects and groups with a note on what they are for there.
//!
//! - A key is generated by the hub (ed25519, `ssh-keygen`) or imported; the private key is
//!   encrypted like project secrets and never returned. People copy the public key into the
//!   server's `authorized_keys`.
//! - "Test" connects once and pins the server's host keys; later connections refuse a
//!   changed host key.
//! - An agent session of a project or group gets its connections without seeing a key:
//!   the hub starts an ssh-agent for the turn with those keys, writes an ssh config with an
//!   alias per connection and wrappers for `ssh` / `scp` / `sftp` (and `GIT_SSH_COMMAND`),
//!   bind-mounts that folder into the sandbox, and lists the connections with their
//!   descriptions in the agent's context — the description tells the agent prod from dev.
//!
//! A port of `ssh.ts`; both servers run the same `ssh-keygen` / `ssh` commands.

use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::time::Duration;

use axum::extract::{Path as UrlPath, State};
use axum::http::StatusCode;
use axum::routing::{get as route_get, post};
use axum::{Json, Router};
use hubness_core::{SshBinding, SshConnection, SshTestResult};
use rusqlite::{Connection, OptionalExtension, params};
use serde::Deserialize;
use serde_json::{Value, json};

use crate::AppState;
use crate::config::Config;
use crate::db;
use crate::error::{ApiResult, HttpError};
use crate::http::JsonBody;
use crate::secrets;

/// AAD namespace of the encrypted private keys (the "project id" of `secrets::encrypt`).
const NS: &str = "ssh";
const COLS: &str = "id, name, host, port, username, environment, description, public_key, host_keys, created_at, updated_at";

fn row(r: &rusqlite::Row) -> rusqlite::Result<SshConnection> {
    Ok(SshConnection {
        id: r.get("id")?,
        name: r.get("name")?,
        host: r.get("host")?,
        port: r.get::<_, i64>("port")?.clamp(1, 65535) as u16,
        username: r.get("username")?,
        environment: r.get("environment")?,
        description: r.get("description")?,
        public_key: r.get("public_key")?,
        host_keys: r.get("host_keys")?,
        created_at: r.get("created_at")?,
        updated_at: r.get("updated_at")?,
    })
}

// ---------- validation ----------

/// The alias: what agents type after `ssh` (letters, digits, `.`, `_`, `-`).
pub fn check_name(name: &str) -> ApiResult<String> {
    let n = name.trim();
    if n.is_empty() || n.len() > 64 || !n.chars().all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '_' | '-')) || n.starts_with('-') {
        return Err(HttpError::bad_request("name: 1-64 latin letters, digits, dots, dashes and underscores"));
    }
    Ok(n.to_string())
}

fn check_host(host: &str) -> ApiResult<String> {
    let h = host.trim();
    let ok = !h.is_empty()
        && h.len() <= 253
        && !h.starts_with('-')
        && h.chars().all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '-' | ':' | '[' | ']' | '_'));
    if !ok {
        return Err(HttpError::bad_request("host: a domain name or an IP address"));
    }
    Ok(h.to_string())
}

fn check_user(user: &str) -> ApiResult<String> {
    let u = user.trim();
    let ok = !u.is_empty()
        && u.len() <= 64
        && !u.starts_with('-')
        && u.chars().all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '_' | '-'));
    if !ok {
        return Err(HttpError::bad_request("username: latin letters, digits, dots, dashes and underscores"));
    }
    Ok(u.to_string())
}

fn check_text(field: &str, v: &str, max: usize) -> ApiResult<String> {
    let t = v.trim();
    if t.encode_utf16().count() > max {
        return Err(HttpError::bad_request(format!("{field}: at most {max} characters")));
    }
    Ok(t.to_string())
}

// ---------- storage ----------

pub fn list(db: &Connection) -> ApiResult<Vec<SshConnection>> {
    let mut st = db.prepare(&format!("SELECT {COLS} FROM ssh_connections ORDER BY name COLLATE NOCASE"))?;
    Ok(st.query_map([], row)?.collect::<rusqlite::Result<_>>()?)
}

fn get(db: &Connection, id: &str) -> ApiResult<SshConnection> {
    db.query_row(&format!("SELECT {COLS} FROM ssh_connections WHERE id = ?"), [id], row)
        .optional()?
        .ok_or_else(|| HttpError::not_found("No such SSH connection"))
}

fn name_taken(db: &Connection, name: &str, except: &str) -> ApiResult<bool> {
    Ok(db
        .query_row("SELECT 1 FROM ssh_connections WHERE name = ? COLLATE NOCASE AND id != ?", params![name, except], |_| Ok(()))
        .optional()?
        .is_some())
}

/// A private folder for one key operation, removed when dropped.
struct Scratch(PathBuf);

impl Scratch {
    fn new(data_dir: &Path) -> ApiResult<Self> {
        use std::os::unix::fs::DirBuilderExt;
        let dir = data_dir.join("ssh").join(format!("tmp-{}", uuid::Uuid::new_v4().simple()));
        std::fs::DirBuilder::new().recursive(true).mode(0o700).create(&dir)?;
        Ok(Self(dir))
    }

    /// Write a private file (0600).
    fn write(&self, name: &str, body: &str) -> ApiResult<PathBuf> {
        use std::io::Write;
        use std::os::unix::fs::OpenOptionsExt;
        let path = self.0.join(name);
        let mut f = std::fs::OpenOptions::new().write(true).create_new(true).mode(0o600).open(&path)?;
        f.write_all(body.as_bytes())?;
        Ok(path)
    }
}

impl Drop for Scratch {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

fn run(cmd: &mut Command) -> ApiResult<String> {
    let out = cmd.stdin(Stdio::null()).output().map_err(|e| HttpError::new(500, format!("{e} (is OpenSSH installed?)")))?;
    if !out.status.success() {
        let err = String::from_utf8_lossy(&out.stderr).trim().to_string();
        return Err(HttpError::bad_request(if err.is_empty() { "ssh-keygen failed".into() } else { err }));
    }
    Ok(String::from_utf8_lossy(&out.stdout).trim().to_string())
}

/// A new ed25519 key pair: (private PEM, public line).
fn generate(data_dir: &Path, comment: &str) -> ApiResult<(String, String)> {
    let tmp = Scratch::new(data_dir)?;
    let key = tmp.0.join("key");
    run(Command::new("ssh-keygen").args(["-q", "-t", "ed25519", "-N", "", "-C", comment, "-f"]).arg(&key))?;
    let private = std::fs::read_to_string(&key)?;
    let public = std::fs::read_to_string(tmp.0.join("key.pub"))?.trim().to_string();
    Ok((private, public))
}

/// The public line of an imported private key (refused with a passphrase).
fn public_of(data_dir: &Path, private: &str) -> ApiResult<String> {
    let tmp = Scratch::new(data_dir)?;
    let mut body = private.trim().replace("\r\n", "\n");
    body.push('\n');
    let key = tmp.write("key", &body)?;
    // -P '' fails at once on a key with a passphrase instead of asking for one
    run(Command::new("ssh-keygen").args(["-y", "-P", "", "-f"]).arg(&key))
        .map_err(|_| HttpError::bad_request("privateKey: not an OpenSSH private key, or it has a passphrase"))
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Input {
    name: String,
    host: String,
    port: Option<u16>,
    username: String,
    environment: Option<String>,
    description: Option<String>,
    private_key: Option<String>,
}

pub fn create(db: &Connection, config: &Config, b: Input) -> ApiResult<SshConnection> {
    let name = check_name(&b.name)?;
    let host = check_host(&b.host)?;
    let username = check_user(&b.username)?;
    let port = b.port.unwrap_or(22).max(1);
    let environment = check_text("environment", b.environment.as_deref().unwrap_or(""), 32)?;
    let description = check_text("description", b.description.as_deref().unwrap_or(""), 4000)?;
    if name_taken(db, &name, "")? {
        return Err(HttpError::new(409, format!("An SSH connection named {name} exists")));
    }
    let (private, public) = match b.private_key.as_deref().map(str::trim).filter(|k| !k.is_empty()) {
        Some(k) if k.len() > 20_000 => return Err(HttpError::bad_request("privateKey: too long")),
        Some(k) => {
            let public = public_of(&config.data_dir, k)?;
            (format!("{k}\n"), public)
        }
        None => generate(&config.data_dir, &format!("hubness:{name}"))?,
    };
    let id = db::new_id();
    let sealed = secrets::encrypt(&secrets::keys(&config.data_dir)?, NS, &id, &private)?;
    let now = db::now();
    db.execute(
        "INSERT INTO ssh_connections (id, name, host, port, username, environment, description, public_key, private_key, host_keys, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, '', ?, ?)",
        params![id, name, host, port, username, environment, description, public, sealed, now, now],
    )?;
    get(db, &id)
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Patch {
    name: Option<String>,
    host: Option<String>,
    port: Option<u16>,
    username: Option<String>,
    environment: Option<String>,
    description: Option<String>,
}

/// Change the details; a new host or port drops the pinned host keys (test again).
pub fn update(db: &Connection, id: &str, b: Patch) -> ApiResult<SshConnection> {
    let cur = get(db, id)?;
    let name = match &b.name {
        Some(n) => check_name(n)?,
        None => cur.name.clone(),
    };
    if name_taken(db, &name, id)? {
        return Err(HttpError::new(409, format!("An SSH connection named {name} exists")));
    }
    let host = match &b.host {
        Some(h) => check_host(h)?,
        None => cur.host.clone(),
    };
    let username = match &b.username {
        Some(u) => check_user(u)?,
        None => cur.username.clone(),
    };
    let port = b.port.unwrap_or(cur.port).max(1);
    let environment = match &b.environment {
        Some(e) => check_text("environment", e, 32)?,
        None => cur.environment.clone(),
    };
    let description = match &b.description {
        Some(d) => check_text("description", d, 4000)?,
        None => cur.description.clone(),
    };
    let host_keys = if host != cur.host || port != cur.port { String::new() } else { cur.host_keys.clone() };
    db.execute(
        "UPDATE ssh_connections SET name = ?, host = ?, port = ?, username = ?, environment = ?, description = ?, host_keys = ?, updated_at = ? WHERE id = ?",
        params![name, host, port, username, environment, description, host_keys, db::now(), id],
    )?;
    get(db, id)
}

pub fn delete(db: &Connection, id: &str) -> ApiResult<()> {
    if db.execute("DELETE FROM ssh_connections WHERE id = ?", [id])? == 0 {
        return Err(HttpError::not_found("No such SSH connection"));
    }
    Ok(())
}

fn private_key(db: &Connection, config: &Config, id: &str) -> ApiResult<String> {
    let blob: String = db.query_row("SELECT private_key FROM ssh_connections WHERE id = ?", [id], |r| r.get(0))?;
    secrets::decrypt(&secrets::keys(&config.data_dir)?, NS, id, &blob)
        .map_err(|e| HttpError::new(500, format!("The key can't be read: {e}")))
}

// ---------- test ----------

/// Connect once (`ssh … true`): accept and pin the host keys the first time, insist on them later.
pub async fn test(state: &AppState, id: &str) -> ApiResult<SshTestResult> {
    let (c, key) = {
        let db = state.db()?;
        (get(&db, id)?, private_key(&db, state.config(), id)?)
    };
    let tmp = Scratch::new(&state.config().data_dir)?;
    let key_path = tmp.write("key", &key)?;
    let known = tmp.write("known_hosts", &c.host_keys)?;
    let strict = if c.host_keys.trim().is_empty() { "accept-new" } else { "yes" };
    let mut cmd = tokio::process::Command::new("ssh");
    cmd.args(["-F", "/dev/null", "-o", "BatchMode=yes", "-o", "ConnectTimeout=10", "-o", "IdentitiesOnly=yes", "-o", "IdentityAgent=none"])
        .arg("-o")
        .arg(format!("StrictHostKeyChecking={strict}"))
        .arg("-o")
        .arg(format!("UserKnownHostsFile={}", known.display()))
        .arg("-i")
        .arg(&key_path)
        .args(["-p", &c.port.to_string(), "-l", &c.username, "--", &c.host, "true"])
        .envs(crate::config::child_env())
        .stdin(Stdio::null())
        .kill_on_drop(true);
    let out = match tokio::time::timeout(Duration::from_secs(20), cmd.output()).await {
        Ok(Ok(o)) => o,
        Ok(Err(e)) => return Err(HttpError::new(500, format!("ssh: {e} (is OpenSSH installed?)"))),
        Err(_) => {
            return Ok(SshTestResult { ok: false, output: "Timed out after 20 s".into(), connection: c });
        }
    };
    let ok = out.status.success();
    let output = String::from_utf8_lossy(&out.stderr).trim().to_string();
    let connection = if ok && c.host_keys.trim().is_empty() {
        let pinned = std::fs::read_to_string(&known).unwrap_or_default();
        let db = state.db()?;
        db.execute("UPDATE ssh_connections SET host_keys = ?, updated_at = ? WHERE id = ?", params![pinned.trim(), db::now(), id])?;
        get(&db, id)?
    } else {
        c
    };
    Ok(SshTestResult { ok, output: if ok { "Connected".into() } else { output }, connection })
}

// ---------- bindings ----------

/// Whose connections: a project or a group.
#[derive(Clone, Copy)]
pub enum Owner<'a> {
    Project(&'a str),
    Group(&'a str),
}

impl Owner<'_> {
    fn column(&self) -> (&'static str, &str) {
        match self {
            Owner::Project(id) => ("project_id", id),
            Owner::Group(id) => ("group_id", id),
        }
    }
}

pub fn bindings(db: &Connection, owner: Owner) -> ApiResult<Vec<SshBinding>> {
    let (col, id) = owner.column();
    let cols: String = COLS.split(", ").map(|c| format!("c.{c}")).collect::<Vec<_>>().join(", ");
    let mut st = db.prepare(&format!(
        "SELECT {cols}, b.note FROM ssh_bindings b JOIN ssh_connections c ON c.id = b.connection_id WHERE b.{col} = ? ORDER BY b.position, c.name"
    ))?;
    let list = st.query_map([id], |r| Ok(SshBinding { connection: row(r)?, note: r.get("note")? }))?.collect::<rusqlite::Result<_>>()?;
    Ok(list)
}

/// `PUT /projects/:id/ssh` and `/groups/:id/ssh`: `{ bindings: [{ connectionId, note }] }`.
#[derive(Deserialize)]
pub struct BindingsBody {
    bindings: Vec<BindingInput>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct BindingInput {
    connection_id: String,
    #[serde(default)]
    note: String,
}

/// Replace the owner's connections (the order given is kept).
pub fn set_bindings(db: &Connection, owner: Owner, list: Vec<BindingInput>) -> ApiResult<Vec<SshBinding>> {
    let (col, id) = owner.column();
    db::tx(db, || {
        db.execute(&format!("DELETE FROM ssh_bindings WHERE {col} = ?"), [id])?;
        let mut seen = std::collections::HashSet::new();
        for (i, b) in list.into_iter().enumerate() {
            if !seen.insert(b.connection_id.clone()) {
                continue;
            }
            get(db, &b.connection_id)?;
            let note = check_text("note", &b.note, 2000)?;
            db.execute(
                &format!("INSERT INTO ssh_bindings (connection_id, {col}, note, position) VALUES (?, ?, ?, ?)"),
                params![b.connection_id, id, note, i as i64],
            )?;
        }
        Ok::<_, HttpError>(())
    })?;
    bindings(db, owner)
}

// ---------- agent sessions ----------

/// What an agent turn gets: an ssh-agent holding the keys, an ssh config with an alias per
/// connection and wrappers; everything goes away when the turn ends (drop).
pub struct SessionSsh {
    dir: PathBuf,
    agent: Option<std::process::Child>,
    pub env: Vec<(String, String)>,
    /// Where the files live (bind-mounted read-only into a sandbox).
    pub mount: String,
    pub context: String,
}

impl Drop for SessionSsh {
    fn drop(&mut self) {
        if let Some(mut a) = self.agent.take() {
            let _ = a.kill();
            let _ = a.wait();
        }
        let _ = std::fs::remove_dir_all(&self.dir);
    }
}

/// `$XDG_RUNTIME_DIR/hubness-ssh`, else `/tmp/hubness-ssh-<uid>` (private to the user).
fn runtime_base() -> PathBuf {
    match std::env::var_os("XDG_RUNTIME_DIR").filter(|v| !v.is_empty()) {
        Some(d) => PathBuf::from(d).join("hubness-ssh"),
        // SAFETY: getuid has no preconditions
        None => std::env::temp_dir().join(format!("hubness-ssh-{}", unsafe { libc::getuid() })),
    }
}

fn which(bin: &str) -> Option<PathBuf> {
    let path = std::env::var_os("PATH")?;
    std::env::split_paths(&path).map(|d| d.join(bin)).find(|p| p.is_file())
}

fn quote(p: &Path) -> String {
    format!("\"{}\"", p.display())
}

/// The ssh config of a session (pure, for tests).
pub fn session_config(list: &[SshBinding], sock: &Path, known: &Path) -> String {
    let mut out = String::from("# hubness: the SSH connections of this session; the keys stay in the hub's agent\n");
    for b in list {
        let c = &b.connection;
        let strict = if c.host_keys.trim().is_empty() { "accept-new" } else { "yes" };
        out.push_str(&format!(
            "\nHost {}\n  HostName {}\n  Port {}\n  User {}\n  IdentityAgent {}\n  UserKnownHostsFile {}\n  StrictHostKeyChecking {strict}\n",
            c.name,
            c.host,
            c.port,
            c.username,
            quote(sock),
            quote(known)
        ));
    }
    // the user's own hosts keep working outside the sandbox
    out.push_str("\nMatch all\n  Include ~/.ssh/config\n");
    out
}

/// The agent's context: each connection with its environment and description.
pub fn session_context(list: &[SshBinding]) -> String {
    let mut out = String::from(
        "## SSH connections\nThese servers are reachable from this session by name: `ssh <name>`, `scp`, `rsync -e ssh`, git over SSH. The hub holds the keys. Read the description before using one — it says what the server is (production or development) and what you may do there. Be careful on production: prefer reading, and ask before changing anything there unless the instructions say otherwise.",
    );
    for b in list {
        let c = &b.connection;
        let env = if c.environment.is_empty() { String::new() } else { format!(" [{}]", c.environment) };
        out.push_str(&format!("\n- `{}`{env} — {}@{}:{}", c.name, c.username, c.host, c.port));
        if !c.description.is_empty() {
            out.push_str(&format!(" — {}", c.description.replace('\n', " ")));
        }
        if !b.note.is_empty() {
            out.push_str(&format!(" In this project: {}", b.note.replace('\n', " ")));
        }
    }
    out
}

/// Set up the connections of a project / group session for one turn (`None` without any,
/// or when OpenSSH is missing).
pub fn session_setup(db: &Connection, config: &Config, owners: &[Owner], session_id: &str) -> ApiResult<Option<SessionSsh>> {
    let mut list: Vec<SshBinding> = vec![];
    for o in owners {
        for b in bindings(db, *o)? {
            if !list.iter().any(|x| x.connection.id == b.connection.id) {
                list.push(b);
            }
        }
    }
    if list.is_empty() {
        return Ok(None);
    }
    let (Some(ssh), Some(agent_bin), Some(add)) = (which("ssh"), which("ssh-agent"), which("ssh-add")) else {
        return Ok(None);
    };
    use std::os::unix::fs::{DirBuilderExt, PermissionsExt};
    // a socket path must stay under ~108 bytes: a short folder in the runtime dir, not in data
    let short: String = session_id.chars().filter(|c| c.is_ascii_alphanumeric()).take(12).collect();
    let dir = runtime_base().join(short);
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::DirBuilder::new().recursive(true).mode(0o700).create(dir.join("bin"))?;
    let mut setup = SessionSsh {
        dir: dir.clone(),
        agent: None,
        env: vec![],
        mount: dir.to_string_lossy().into_owned(),
        context: session_context(&list),
    };
    let sock = dir.join("agent.sock");
    let known = dir.join("known_hosts");
    let hosts: String = list.iter().map(|b| b.connection.host_keys.trim()).filter(|k| !k.is_empty()).collect::<Vec<_>>().join("\n");
    std::fs::write(&known, if hosts.is_empty() { hosts } else { hosts + "\n" })?;
    std::fs::write(dir.join("config"), session_config(&list, &sock, &known))?;
    for (name, real) in [("ssh", ssh.clone()), ("scp", which("scp").unwrap_or_default()), ("sftp", which("sftp").unwrap_or_default())] {
        if real.as_os_str().is_empty() {
            continue;
        }
        let wrapper = dir.join("bin").join(name);
        std::fs::write(&wrapper, format!("#!/bin/sh\nexec {} -F {} \"$@\"\n", quote(&real), quote(&dir.join("config"))))?;
        std::fs::set_permissions(&wrapper, std::fs::Permissions::from_mode(0o755))?;
    }
    // the session's own agent: the keys are usable through the socket, never readable
    let child = Command::new(agent_bin)
        .args(["-D", "-a"])
        .arg(&sock)
        .envs(crate::config::child_env())
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()?;
    setup.agent = Some(child);
    for _ in 0..50 {
        if sock.exists() {
            break;
        }
        std::thread::sleep(Duration::from_millis(40));
    }
    let tmp = Scratch::new(&config.data_dir)?;
    for (i, b) in list.iter().enumerate() {
        let key = tmp.write(&format!("k{i}"), &private_key(db, config, &b.connection.id)?)?;
        let _ = Command::new(&add)
            .arg("-q")
            .arg(&key)
            .env("SSH_AUTH_SOCK", &sock)
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status();
        let _ = std::fs::remove_file(&key);
    }
    let path = std::env::var("PATH").unwrap_or_default();
    setup.env = vec![
        ("SSH_AUTH_SOCK".into(), sock.to_string_lossy().into_owned()),
        ("PATH".into(), format!("{}:{path}", dir.join("bin").display())),
        ("GIT_SSH_COMMAND".into(), dir.join("bin").join("ssh").to_string_lossy().into_owned()),
    ];
    Ok(Some(setup))
}

// ---------- routes ----------

pub fn routes() -> Router<AppState> {
    Router::new()
        .route("/ssh", route_get(list_route).post(create_route))
        .route("/ssh/{id}", axum::routing::patch(update_route).delete(delete_route))
        .route("/ssh/{id}/test", post(test_route))
        .route("/projects/{id}/ssh", route_get(project_get).put(project_put))
        .route("/groups/{id}/ssh", route_get(group_get).put(group_put))
}

async fn list_route(State(s): State<AppState>) -> ApiResult<Json<Vec<SshConnection>>> {
    s.with(|db, _| list(db))
}

async fn create_route(State(s): State<AppState>, JsonBody(b): JsonBody<Input>) -> ApiResult<(StatusCode, Json<SshConnection>)> {
    let state = s.clone();
    // ssh-keygen is a short blocking call
    let c = tokio::task::spawn_blocking(move || {
        let db = state.db()?;
        create(&db, state.config(), b)
    })
    .await
    .map_err(|e| HttpError::new(500, e.to_string()))??;
    Ok((StatusCode::CREATED, Json(c)))
}

async fn update_route(
    State(s): State<AppState>,
    UrlPath(id): UrlPath<String>,
    JsonBody(b): JsonBody<Patch>,
) -> ApiResult<Json<SshConnection>> {
    s.with(|db, _| update(db, &id, b))
}

async fn delete_route(State(s): State<AppState>, UrlPath(id): UrlPath<String>) -> ApiResult<Json<Value>> {
    s.with(|db, _| delete(db, &id).map(|_| json!({ "ok": true })))
}

async fn test_route(State(s): State<AppState>, UrlPath(id): UrlPath<String>) -> ApiResult<Json<SshTestResult>> {
    Ok(Json(test(&s, &id).await?))
}

