#[cfg(test)]
mod tests {
    use super::*;

    fn conn(name: &str, env: &str, keys: &str) -> SshBinding {
        SshBinding {
            connection: SshConnection {
                id: name.into(),
                name: name.into(),
                host: "10.0.0.5".into(),
                port: 2222,
                username: "deploy".into(),
                environment: env.into(),
                description: "Backend API".into(),
                public_key: String::new(),
                host_keys: keys.into(),
                created_at: String::new(),
                updated_at: String::new(),
            },
            note: "deploy only after tests pass".into(),
        }
    }

    #[test]
    fn names_hosts_users() {
        assert_eq!(check_name(" prod-api ").unwrap(), "prod-api");
        assert!(check_name("bad name").is_err() && check_name("-x").is_err() && check_name("").is_err());
        assert!(check_host("db.example.com").is_ok() && check_host("10.0.0.5").is_ok() && check_host("[::1]").is_ok());
        assert!(check_host("a b").is_err() && check_host("-oProxyCommand=x").is_err());
        assert!(check_user("deploy").is_ok() && check_user("-l").is_err() && check_user("a b").is_err());
    }

    #[test]
    fn config_pins_tested_hosts_and_keeps_the_users_own() {
        let list = [conn("prod-api", "prod", "10.0.0.5 ssh-ed25519 AAAA"), conn("dev-api", "dev", "")];
        let cfg = session_config(&list, Path::new("/d/agent.sock"), Path::new("/d/known_hosts"));
        assert!(cfg.contains("Host prod-api\n  HostName 10.0.0.5\n  Port 2222\n  User deploy\n  IdentityAgent \"/d/agent.sock\""));
        assert!(cfg.contains("Host prod-api") && cfg.contains("StrictHostKeyChecking yes"));
        assert!(cfg.contains("Host dev-api") && cfg.contains("StrictHostKeyChecking accept-new"));
        assert!(cfg.trim_end().ends_with("Include ~/.ssh/config"));
        let ctx = session_context(&list);
        assert!(ctx.contains("`prod-api` [prod] — deploy@10.0.0.5:2222 — Backend API In this project: deploy only after tests pass"));
    }
}
